// Bank wire / ACH payment details, shared by the order emails.
//
// Team request (2026-09-14): larger orders are awkward over Zelle / Venmo
// limits. The wholesale order email always shows this block; the retail /
// Inner Circle order email shows it when the order total is $1,000 or more
// (WIRE_THRESHOLD). Both attach the letterhead PDF (WIRE_PDF_BASE64, built
// from VCP_Wire_Instructions.docx in Josh's Claude outputs folder) so the
// customer has a printable copy.

export const WIRE_THRESHOLD = 1000;

export const WIRE = {
  bank: "Wells Fargo Bank, N.A.",
  bankAddress: "601 N El Camino Real, San Clemente, CA 92672",
  beneficiary: "Vitality Certified Peptides LLC",
  accountType: "Checking",
  beneficiaryAddress: "216 Avenida Fabricante, Suite 110, San Clemente, CA 92672",
  achRouting: "121042882",
  wireRouting: "121000248",
  swift: "WFBIUS6S",
  account: "9751508574",
} as const;

export const WIRE_PDF_FILENAME = "VCP-Wire-Instructions.pdf";

export function wireAttachment(): { filename: string; content: string } {
  return { filename: WIRE_PDF_FILENAME, content: WIRE_PDF_BASE64 };
}

export function wireCardHtml(orderNumber: string, colors: { ink: string; muted: string; gold: string; cardBg: string; border: string }, opts: { headline?: string } = {}): string {
  const { ink, muted, gold, cardBg, border } = colors;
  const headline = opts.headline ?? "BANK WIRE / ACH &mdash; RECOMMENDED FOR LARGER ORDERS";
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; margin:0 0 4px;">
    <tr><td style="padding:8px;">
      <div style="background:${cardBg}; border:1px solid ${border}; border-radius:10px; padding:16px 18px;">
        <div style="font-size:13px; font-weight:bold; letter-spacing:0.3px; color:${ink}; margin-bottom:4px;">${headline}</div>
        <div style="font-size:12px; color:${muted}; margin-bottom:10px;">${WIRE.bank} &middot; Beneficiary: ${WIRE.beneficiary} (${WIRE.accountType.toLowerCase()}), ${WIRE.beneficiaryAddress}</div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; font-size:13px; color:${ink};">
          <tr>
            <td width="34%" valign="top" style="padding:4px 6px 4px 0;"><span style="font-size:11px; color:${gold}; letter-spacing:0.5px;">ACH / DIRECT DEPOSIT</span><br/>Routing <strong>${WIRE.achRouting}</strong></td>
            <td width="33%" valign="top" style="padding:4px 6px;"><span style="font-size:11px; color:${gold}; letter-spacing:0.5px;">DOMESTIC WIRE</span><br/>Routing <strong>${WIRE.wireRouting}</strong></td>
            <td width="33%" valign="top" style="padding:4px 0 4px 6px;"><span style="font-size:11px; color:${gold}; letter-spacing:0.5px;">INTERNATIONAL</span><br/>SWIFT <strong>${WIRE.swift}</strong></td>
          </tr>
          <tr><td colspan="3" style="padding:6px 0 2px;">Account number <strong>${WIRE.account}</strong> &nbsp;&middot;&nbsp; Bank address: ${WIRE.bankAddress}</td></tr>
        </table>
        <div style="font-size:12px; color:${muted}; margin-top:10px;">Put <strong>#${orderNumber}</strong> in the wire memo. Wire fees from your bank are separate from the order total. Printable wiring instructions are attached to this email.</div>
      </div>
    </td></tr>
  </table>`;
}

export function wireText(orderNumber: string): string {
  return [
    `Bank wire / ACH (recommended for larger orders): ${WIRE.bank} - Beneficiary ${WIRE.beneficiary} (${WIRE.accountType.toLowerCase()}), ${WIRE.beneficiaryAddress}`,
    `  ACH / direct deposit routing ${WIRE.achRouting} - Domestic wire routing ${WIRE.wireRouting} - International SWIFT ${WIRE.swift} - Account ${WIRE.account}`,
    `  Bank address ${WIRE.bankAddress}. Put #${orderNumber} in the wire memo. Printable wiring instructions are attached.`,
  ].join("\n");
}

// prettier-ignore
export const WIRE_PDF_BASE64 = "";
